CREATE TYPE public.crm_foundation_role AS ENUM ('admin','staff');
ALTER TABLE public.org_members ADD COLUMN foundation_role public.crm_foundation_role;
UPDATE public.org_members SET foundation_role = CASE WHEN role IN ('owner','super_admin','admin') THEN 'admin'::public.crm_foundation_role WHEN role IN ('employee','manager','case_manager') THEN 'staff'::public.crm_foundation_role ELSE NULL END;
CREATE FUNCTION private.foundation_member_role() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$ BEGIN NEW.foundation_role := CASE WHEN NEW.role IN ('owner','super_admin','admin') THEN 'admin'::public.crm_foundation_role WHEN NEW.role IN ('employee','manager','case_manager') THEN 'staff'::public.crm_foundation_role ELSE NULL END; RETURN NEW; END $$;
CREATE TRIGGER foundation_member_role BEFORE INSERT OR UPDATE ON public.org_members FOR EACH ROW EXECUTE FUNCTION private.foundation_member_role();
CREATE FUNCTION private.foundation_staff(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS(SELECT 1 FROM public.org_members WHERE organization_id=org AND user_id=auth.uid() AND active AND foundation_role IN ('admin','staff')); $$;
CREATE FUNCTION private.foundation_admin(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS(SELECT 1 FROM public.org_members WHERE organization_id=org AND user_id=auth.uid() AND active AND foundation_role='admin'); $$;
GRANT USAGE ON SCHEMA private TO authenticated;
GRANT EXECUTE ON FUNCTION private.foundation_staff(uuid),private.foundation_admin(uuid) TO authenticated;
REVOKE ALL ON FUNCTION private.foundation_staff(uuid),private.foundation_admin(uuid) FROM PUBLIC,anon;
CREATE SEQUENCE public.crm_client_number_seq;
REVOKE ALL ON SEQUENCE public.crm_client_number_seq FROM PUBLIC,anon,authenticated;
GRANT ALL ON SEQUENCE public.crm_client_number_seq TO service_role;
CREATE TABLE public.crm_number_counters(service text NOT NULL CHECK(service IN ('IMM','ADM','BUD')), year integer NOT NULL, value integer NOT NULL DEFAULT 0, PRIMARY KEY(service,year));
GRANT ALL ON public.crm_number_counters TO service_role;
ALTER TABLE public.crm_number_counters ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_clients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),number text NOT NULL DEFAULT '',type text NOT NULL CHECK(type IN ('person','household','company')),first_name text NOT NULL DEFAULT '',last_name text NOT NULL DEFAULT '',company_name text NOT NULL DEFAULT '',household_name text NOT NULL DEFAULT '',enterprise_number text NOT NULL DEFAULT '',contact_person_id uuid,preferred_language text NOT NULL DEFAULT 'nl' CHECK(preferred_language IN ('nl','fr','en','other')),phone text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',whatsapp text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',nationality text NOT NULL DEFAULT '',birth_date date,notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(number),UNIQUE(id,organization_id),FOREIGN KEY(contact_person_id,organization_id) REFERENCES public.crm_clients(id,organization_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_clients TO authenticated;
GRANT ALL ON public.crm_clients TO service_role;
ALTER TABLE public.crm_clients ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_clients ON public.crm_clients FOR ALL TO authenticated USING(private.foundation_staff(organization_id)) WITH CHECK(private.foundation_staff(organization_id));
CREATE TABLE public.crm_client_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),client_id uuid NOT NULL,person_id uuid NOT NULL,role text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(client_id,organization_id) REFERENCES public.crm_clients(id,organization_id) ON DELETE CASCADE,FOREIGN KEY(person_id,organization_id) REFERENCES public.crm_clients(id,organization_id),UNIQUE(client_id,person_id),CHECK(client_id<>person_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_client_links TO authenticated;
GRANT ALL ON public.crm_client_links TO service_role;
ALTER TABLE public.crm_client_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_links ON public.crm_client_links FOR ALL TO authenticated USING(private.foundation_staff(organization_id)) WITH CHECK(private.foundation_staff(organization_id));
CREATE TABLE public.crm_dossiers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),client_id uuid NOT NULL,number text NOT NULL DEFAULT '',service text NOT NULL CHECK(service IN ('IMM','ADM','BUD')),title text NOT NULL,status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','ongoing','waiting_client','waiting_authority','completed','archived')),responsible_id uuid,start_date date NOT NULL DEFAULT CURRENT_DATE,next_step text NOT NULL DEFAULT '',next_step_date date,priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('normal','high','urgent')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(number),UNIQUE(id,organization_id),FOREIGN KEY(client_id,organization_id) REFERENCES public.crm_clients(id,organization_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_dossiers TO authenticated;
GRANT ALL ON public.crm_dossiers TO service_role;
ALTER TABLE public.crm_dossiers ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_dossiers ON public.crm_dossiers FOR ALL TO authenticated USING(private.foundation_staff(organization_id)) WITH CHECK(private.foundation_staff(organization_id));
CREATE TABLE public.crm_timeline(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),client_id uuid NOT NULL,dossier_id uuid,kind text NOT NULL CHECK(kind IN ('client_created','dossier_created','status_changed','contact','note')),body text NOT NULL DEFAULT '',detail jsonb NOT NULL DEFAULT '{}',actor_id uuid,actor_name text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(client_id,organization_id) REFERENCES public.crm_clients(id,organization_id),FOREIGN KEY(dossier_id,organization_id) REFERENCES public.crm_dossiers(id,organization_id));
GRANT SELECT,INSERT ON public.crm_timeline TO authenticated;
GRANT ALL ON public.crm_timeline TO service_role;
ALTER TABLE public.crm_timeline ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_timeline_read ON public.crm_timeline FOR SELECT TO authenticated USING(private.foundation_staff(organization_id));
CREATE POLICY staff_timeline_insert ON public.crm_timeline FOR INSERT TO authenticated WITH CHECK(private.foundation_staff(organization_id) AND actor_id=auth.uid() AND kind IN ('note','contact'));
CREATE TABLE public.crm_access_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),client_id uuid NOT NULL,user_id uuid NOT NULL DEFAULT auth.uid(),opened_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(client_id,organization_id) REFERENCES public.crm_clients(id,organization_id));
GRANT SELECT,INSERT ON public.crm_access_log TO authenticated;
GRANT ALL ON public.crm_access_log TO service_role;
ALTER TABLE public.crm_access_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY access_log_insert ON public.crm_access_log FOR INSERT TO authenticated WITH CHECK(private.foundation_staff(organization_id) AND user_id=auth.uid());
CREATE POLICY access_log_read ON public.crm_access_log FOR SELECT TO authenticated USING(private.foundation_admin(organization_id));
CREATE TABLE public.crm_preferences(user_id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES public.organizations(id),language text NOT NULL DEFAULT 'nl' CHECK(language IN ('nl','fr')),theme text NOT NULL DEFAULT 'system' CHECK(theme IN ('system','light','dark')));
GRANT SELECT,INSERT,UPDATE ON public.crm_preferences TO authenticated;
GRANT ALL ON public.crm_preferences TO service_role;
ALTER TABLE public.crm_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_preferences ON public.crm_preferences FOR ALL TO authenticated USING(user_id=auth.uid() AND private.foundation_staff(organization_id)) WITH CHECK(user_id=auth.uid() AND private.foundation_staff(organization_id));
CREATE FUNCTION private.foundation_client_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.number := 'K-'||lpad(nextval('public.crm_client_number_seq')::text,4,'0'); ELSE IF NEW.number<>OLD.number OR NEW.organization_id<>OLD.organization_id OR NEW.type<>OLD.type THEN RAISE EXCEPTION 'Immutable client identity'; END IF; END IF; IF NEW.type='person' AND (btrim(NEW.first_name)='' OR btrim(NEW.last_name)='') THEN RAISE EXCEPTION 'Person name required'; END IF; IF NEW.type='company' AND btrim(NEW.company_name)='' THEN RAISE EXCEPTION 'Company name required'; END IF; IF NEW.type='household' AND btrim(NEW.household_name)='' THEN RAISE EXCEPTION 'Household name required'; END IF; IF NEW.contact_person_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.crm_clients WHERE id=NEW.contact_person_id AND organization_id=NEW.organization_id AND type='person') THEN RAISE EXCEPTION 'Invalid contact person'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER foundation_client_validate BEFORE INSERT OR UPDATE ON public.crm_clients FOR EACH ROW EXECUTE FUNCTION private.foundation_client_validate();
CREATE FUNCTION private.foundation_link_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.crm_clients WHERE id=NEW.person_id AND organization_id=NEW.organization_id AND type='person') OR NOT EXISTS(SELECT 1 FROM public.crm_clients WHERE id=NEW.client_id AND organization_id=NEW.organization_id AND type IN ('household','company')) THEN RAISE EXCEPTION 'Invalid person relationship'; END IF; RETURN NEW; END $$;
CREATE TRIGGER foundation_link_validate BEFORE INSERT OR UPDATE ON public.crm_client_links FOR EACH ROW EXECUTE FUNCTION private.foundation_link_validate();
CREATE FUNCTION private.foundation_dossier_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE seq integer; yr integer; BEGIN IF TG_OP='INSERT' THEN yr:=extract(year FROM CURRENT_DATE); INSERT INTO public.crm_number_counters(service,year,value) VALUES(NEW.service,yr,1) ON CONFLICT(service,year) DO UPDATE SET value=public.crm_number_counters.value+1 RETURNING value INTO seq; NEW.number:=NEW.service||'-'||yr||'-'||lpad(seq::text,4,'0'); ELSE IF NEW.number<>OLD.number OR NEW.service<>OLD.service OR NEW.client_id<>OLD.client_id OR NEW.organization_id<>OLD.organization_id THEN RAISE EXCEPTION 'Immutable dossier identity'; END IF; END IF; IF NEW.responsible_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_members WHERE organization_id=NEW.organization_id AND user_id=NEW.responsible_id AND active AND foundation_role IS NOT NULL) THEN RAISE EXCEPTION 'Invalid responsible member'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER foundation_dossier_validate BEFORE INSERT OR UPDATE ON public.crm_dossiers FOR EACH ROW EXECUTE FUNCTION private.foundation_dossier_validate();
CREATE FUNCTION private.foundation_actor_stamp() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN NEW.actor_id:=auth.uid(); SELECT coalesce(nullif(full_name,''),email) INTO NEW.actor_name FROM public.org_members WHERE user_id=auth.uid() AND organization_id=NEW.organization_id AND active LIMIT 1; NEW.actor_name:=coalesce(NEW.actor_name,''); NEW.created_at:=now(); IF NEW.dossier_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.crm_dossiers WHERE id=NEW.dossier_id AND client_id=NEW.client_id AND organization_id=NEW.organization_id) THEN RAISE EXCEPTION 'Invalid timeline dossier'; END IF; RETURN NEW; END $$;
CREATE TRIGGER foundation_actor_stamp BEFORE INSERT ON public.crm_timeline FOR EACH ROW EXECUTE FUNCTION private.foundation_actor_stamp();
CREATE FUNCTION private.foundation_auto_timeline() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF TG_TABLE_NAME='crm_clients' THEN INSERT INTO public.crm_timeline(organization_id,client_id,kind,detail) VALUES(NEW.organization_id,NEW.id,'client_created',jsonb_build_object('number',NEW.number)); ELSIF TG_OP='INSERT' THEN INSERT INTO public.crm_timeline(organization_id,client_id,dossier_id,kind,detail) VALUES(NEW.organization_id,NEW.client_id,NEW.id,'dossier_created',jsonb_build_object('number',NEW.number,'title',NEW.title)); ELSIF OLD.status<>NEW.status THEN INSERT INTO public.crm_timeline(organization_id,client_id,dossier_id,kind,detail) VALUES(NEW.organization_id,NEW.client_id,NEW.id,'status_changed',jsonb_build_object('from',OLD.status,'to',NEW.status,'number',NEW.number)); END IF; RETURN NEW; END $$;
CREATE TRIGGER foundation_client_timeline AFTER INSERT ON public.crm_clients FOR EACH ROW EXECUTE FUNCTION private.foundation_auto_timeline();
CREATE TRIGGER foundation_dossier_timeline AFTER INSERT OR UPDATE ON public.crm_dossiers FOR EACH ROW EXECUTE FUNCTION private.foundation_auto_timeline();
CREATE INDEX crm_clients_org ON public.crm_clients(organization_id,created_at DESC);
CREATE INDEX crm_dossiers_org ON public.crm_dossiers(organization_id,next_step_date);
CREATE INDEX crm_timeline_client ON public.crm_timeline(client_id,created_at DESC);
COMMENT ON TABLE public.clients IS 'DEPRECATED: old test CRM; Phase 1 uses crm_clients. Retained for legacy mandate/Gmail contracts.';
COMMENT ON TABLE public.cases IS 'DEPRECATED: old test CRM; Phase 1 uses crm_dossiers. Retained for legacy mandate/Gmail contracts.';